### Instruction:
Create an HTML page with a text box that stores entered data in the local storage.

### Response:
<html>
<head>
  <title>Text Box</title>
</head>

<body>
  <input type="text" id="text_box" />
</body>

<script>
  // Store data in localStorage
  function storeData() {
    let inputValue = document.getElementById("text_box").value;
    localStorage.setItem("inputValue", inputValue);
  }

  // Set the text box value from localStorage
  window.onload = () => {
    if(localStorage.getItem("inputValue"))
      document.getElementById("text_box").value = localStorage.getItem("inputValue");
  }

  // Set up the event listener
  document.getElementById('text_box').addEventListener('input', storeData);
</script>

</html>

