### Instruction:
Create a web page that displays a message in different languages by using HTML, CSS, and JavaScript.

### Response:
<!DOCTYPE html>
<html>
<head>
  <title>Hello World in Different Languages</title>
  <style>
    body {
      font-family: sans-serif;
      background-color: #eee;
      text-align: center;
      padding: 20px;
    }
    select {
      background-color: #f0f0f0;
      font-size: 1rem;
      padding: 5px 10px;
      margin-top: 20px;
      border: none;
      border-radius: 5px;
    }
    button {
      background-color: #444;
      color: #fff;
      font-size: 1rem;
      padding: 5px 10px;
      margin-top: 20px;
      border: none;
      border-radius: 5px;
    }
    .language-message {
      font-size: 2rem;
      margin: 20px;
      color: #444;
    }
  </style>
</head>
<body>
  <h1>Hello World in Different Languages</h1>
  <select id="language-selector">
    <option value="English">English</option>
    <option value="French">French</option>
    <option value="Spanish">Spanish</option>
    <option value="German">German</option>
    <option value="Italian">Italian</option>
  </select>
  <button type="button" id="language-button">Show!</button>
  <label class="language-message" id="language-message"></label>

  <script>
    // Get language button, message label, and language selector elements
    const languageButton = document.querySelector('#language-button');
    const languageMessage = document.querySelector('#language-message');
    const languageSelector = document.querySelector('#language-selector');

    let messages = {
      'English': 'Hello, World!',
      'French': 'Bonjour le monde!',
      'Spanish': 'Hola Mundo!',
      'German': 'Hallo Welt!',
      'Italian': 'Ciao Mondo!'
    };

    languageButton.addEventListener('click', () => {
      let language = languageSelector.value;
      languageMessage.innerText = messages[language];
    });
  </script>
</body>
</html>

