### Instruction:
Create an HTML form with two dropdowns to select from different countries and cities.

### Response:
<form action="">
  <label>Country:</label>
  <select id="country">
    <option value="">-- Select Country --</option>
    <option value="us">USA</option>
    <option value="uk">UK</option>
  </select>
  <label>City:</label>
  <select id="city">
    <option value="">-- Select City --</option>
    <option value="ny" class="us">New York</option>
    <option value="la" class="us">Los Angeles</option>
    <option value="london" class="uk">London</option>
    <option value="oxford" class="uk">Oxford</option>
  </select>
</form>

<script>
  const countrySelect = document.querySelector('#country');
  const citySelect = document.querySelector('#city');

  countrySelect.addEventListener('change', (e) => {
    const selectedOption = e.target.value;
    citySelect.innerHTML = '<option value="">-- Select City --</option>';
    document.querySelectorAll('.${selectedOption}').forEach((option) => {
      citySelect.innerHTML += option.outerHTML;
    });
  });
</script>

